import re,json,os
WALL_KEY='mscfanht'  # keyvalue.immanuel.co app key for live wall posts (free, no login)
TV=lambda fn: fn.startswith('learn/') or fn in('today.html','tracker.html','learning.html')
def NAV2(fn):
    p='../'*fn.count('/'); v='res' if fn.startswith('results/') else ('tom' if TV(fn) else 'sup')
    sw=lambda k,h,t:f'<a href="{p}{h}" class="vs{" on" if v==k else ""}"{" aria-current=page" if v==k else ""}>{t}</a>'
    sub={'sup':[('index.html','Home'),('wall.html','Wall of support'),('support.html','How to help'),('tracker.html','Tracker'),('skills.html','Skills'),('careers.html','Careers'),('plan/index.html','Plan'),('library/index.html','Library')],
         'tom':[('learn/index.html','My dashboard'),('today.html','Today'),('learn/index.html#days','21 days'),('learn/index.html#lessons','Lessons'),('learn/tools.html','Tools'),('tracker.html','My log'),('wall.html','My crew')],
         'res':[('results/index.html','Results'),('results/index.html#log','Build log'),('results/index.html#site','Site versions'),('results/index.html#skills','Skills earned'),('results/burdekin.html','Burdekin concept')]}[v]
    return (f'<a class="skip" href="#main">Skip to content</a><nav aria-label="Main"><div class="w nv"><a class="logo" href="{p}index.html" style="text-decoration:none">Tomas <span>Levels Up</span></a>'
     f'<div class="vsw" role="group" aria-label="Choose a view">{sw("sup","index.html","👪 Supporters&rsquo; view")}{sw("tom","learn/index.html","🎓 Tomas&rsquo;s view")}{sw("res","results/index.html","🏆 Results")}</div></div>'
     f'<div class="w"><ul class="sub">'+''.join(f'<li><a href="{p}{h}">{t}</a></li>' for h,t in sub)+'</ul></div></nav>')
def fixnav(fn):
    s=open(fn).read()
    s2=re.sub(r'<a class="skip" href="#main">Skip to content</a><nav aria-label="Main">.*?</nav>',lambda m:NAV2(fn),s,count=1,flags=re.S)
    if s2!=s: open(fn,'w').write(s2)
