WALLJS='''<script>
var WKV="https://keyvalue.immanuel.co/api/KeyVal/",WAK="'''+WALL_KEY+'''";
function wkGet(k){return fetch(WKV+"GetValue/"+WAK+"/"+k+"?"+Date.now()).then(r=>r.json()).then(v=>v||"")}
function wkDec(s){s=s.replace(/-/g,"+").replace(/_/g,"/");while(s.length%4)s+="=";return JSON.parse(decodeURIComponent(escape(atob(s))))}
function wallLive(){return wkGet("n").then(function(n){n=parseInt(n)||0;var ps=[];for(var i=1;i<=n;i++)ps.push((function(i){return wkGet("m"+i).then(function(c){c=parseInt(c)||0;if(!c)return null;var cs=[];for(var j=0;j<c;j++)cs.push(wkGet("m"+i+"_"+j));return Promise.all(cs).then(a=>{var x=wkDec(a.join(""));x._id=i;return x})}).catch(()=>null)})(i));return Promise.all(ps)}).then(a=>a.filter(Boolean)).catch(()=>[])}
function wallRender(el,opts){Promise.all([fetch(opts.base+"wall.json?"+Date.now()).then(r=>r.json()).then(d=>d.items||[]).catch(()=>[]),wallLive()]).then(function(r){var m=r[0].concat(r[1]).filter(x=>!opts.type||x.type==opts.type);if(opts.limit)m=m.slice(-opts.limit);
if(!m.length){el.innerHTML='<p class="note">'+opts.empty+'</p>';return}
var K={message:"💬 Message",advice:"🧭 Advice",offer:"🎁 Offer"};el.innerHTML=m.reverse().map(function(x){var e=function(s){return String(s||"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))};
return '<div class="wm"><div class="k">'+(K[x.type]||K.message)+(x.offer?' · '+e(x.offer):'')+'</div><p>'+e(x.text)+'</p>'+(x.milestone?'<p class="f">🎯 '+e(x.milestone)+(x.when?' · '+e(x.when):'')+'</p>':'')+'<p class="f">— '+e(x.from)+'</p></div>'}).join("")})}
</script>'''
