WFJS=f'''<script>(function(){{var T="message",O="",f=document.getElementById("wf");document.querySelectorAll(".tabs button").forEach(function(b){{b.onclick=function(){{T=b.dataset.t;document.querySelectorAll(".tabs button").forEach(x=>x.setAttribute("aria-selected",x==b));document.getElementById("ofr").hidden=T!="offer";document.getElementById("wlab").textContent={{message:"Your message to Tomas",advice:"Your advice for Tomas",offer:"A note to go with your offer"}}[T]}}}});
document.querySelectorAll(".offer").forEach(function(b){{b.onclick=function(){{O=b.dataset.o;document.querySelectorAll(".offer").forEach(x=>x.setAttribute("aria-pressed",x==b))}}}});
f.onsubmit=function(e){{e.preventDefault();var v=id=>document.getElementById(id).value.trim();var ok=document.getElementById("wok");var item={{type:T,from:v("wfrom"),text:v("wtxt"),date:new Date().toISOString().slice(0,10)}};if(T=="offer"){{item.offer=O||"Something else";item.milestone=v("wmil");item.when=v("wwhen")}}
if(v("wweb")){{f.reset();ok.textContent="Thanks! Your message is on the wall.";return}}if(!item.text||!item.from||item.text.length>500||item.from.length>60){{ok.textContent="Please add a message (up to 500 characters) and who it's from.";return}}
var last=+localStorage.getItem("wallLast")||0;if(Date.now()-last<20000){{ok.textContent="Just a moment, then try again.";return}}
var btn=f.querySelector("button[type=submit]");btn.disabled=true;ok.textContent="Posting…";
var enc=btoa(unescape(encodeURIComponent(JSON.stringify(item)))).replace(/[+]/g,"-").replace(/[/]/g,"_").replace(/=+$/,""),ch=[];for(var i=0;i<enc.length;i+=180)ch.push(enc.slice(i,i+180));
var put=(k,val)=>fetch(WKV+"UpdateValue/"+WAK+"/"+k+"/"+val,{{method:"POST"}}).then(r=>{{if(!r.ok)throw 0}});
function claim(t){{return wkGet("n").then(function(n){{var id=(parseInt(n)||0)+1;return put("n",id).then(()=>wkGet("m"+id)).then(function(c){{if(parseInt(c)&&t<5)return claim(t+1);return id}})}})}}
claim(0).then(function(id){{return Promise.all(ch.map((c,j)=>put("m"+id+"_"+j,c))).then(()=>put("m"+id,ch.length))}}).then(function(){{localStorage.setItem("wallLast",Date.now());ok.textContent="Thanks, "+item.from+"! Your message is on Tomas’s wall. 💛";f.reset();btn.disabled=false;wallRender(document.getElementById("wall"),{{base:"",empty:""}})}}).catch(function(){{btn.disabled=false;ok.textContent="Sorry, that didn't post. Please try again in a minute."}})}}}})();</script>'''
